from pathlib import Path
import hashlib, json, shutil
HERE=Path(__file__).resolve().parent; ROOT=HERE.parents[3]; R=ROOT/'.model-research'; A=R/'system-assets'; MP=R/'mpfb2-2.0.18'
folders=['clothes/male_casualsuit02','clothes/shoes01','eyes/low-poly','hair/short01','eyebrows/eyebrow001','skins/middleage_caucasian_male']
paths=[p for folder in folders for p in (A/folder).rglob('*') if p.is_file()]
paths += [MP/'src/mpfb/data/3dobjs/base.obj',MP/'src/mpfb/data/rigs/standard/rig.game_engine.json',MP/'src/mpfb/data/rigs/standard/weights.game_engine.json',MP/'LICENSE.md',MP/'LICENSE.ASSETS.md']
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
for name in ('LICENSE.md','LICENSE.ASSETS.md'): shutil.copyfile(MP/name,HERE/'source'/name)
provenance={'route':'B: fresh MPFB base + official verified CC0 system assets','url':'https://github.com/makehumancommunity/mpfb2','author':'MakeHuman Community; Data Collection AB; Joel Palmius; Jonas Hauquier','licence':'CC0 1.0 Universal assets; addon source separately GPLv3','verification_date':'2026-10-22','retrieved':'Existing locally preserved official sources, not re-downloaded','licence_evidence':['source/LICENSE.md sections C,D','source/LICENSE.ASSETS.md','CC0 September 2020 headers on adopted MHCLO and materials'],'changes':['Fresh civilian macro body, no officer targets or equipment','Original top texture replaced by plain teal; connected denim trousers retained as geometry','Shoes01 trimmed to low upper with each rigid shoe bound to foot','Hair/brows low-alpha polygons removed once; opaque output','Analytic constrained scooter riding/crouch; fixed hands, tandem supported soles','One ride-only 2048 atlas; coordinates-only duck deformation'],'sources':[{'path':str(p.relative_to(ROOT)).replace('\\','/'),'sha256':sha(p)} for p in sorted(paths)],'reference_photos':'refs.json: pose/context reference only, no image pixels used in textures; not adopted model data'}
(HERE/'provenance.json').write_text(json.dumps(provenance,indent=2))
spec={'route':'B','detail_level':'custom','tri_budget':35000,'tex_res':2048,'workflow':'sections','poses':['ride','duck'],'display':'mutually_exclusive','facing':'Blender +Y','origin':[0,0,0],'grip_axis_midpoints':[[-.235,.2681990457,.982],[.235,.2681990457,.982]],'grip_radius':.018,'deck':{'x':[-.09,.09],'y':[-.291,.214],'top_z':.184},'contact_source':'scooter_voi/build.py and spec.json; exact measured formulas documented in rider scout','macro':{'gender':1,'age':.38,'muscle':.40,'weight':.48,'height':.40},'pose_frames':{'ride':1,'duck':2},'author_choices':'generic civilian proportions/wardrobe, photo1 riding category and pose; photo2 context only'}
(HERE/'spec.json').write_text(json.dumps(spec,indent=2))
(HERE/'BRIEF.md').write_text('''# Civilian scooter rider\n\nApproved essential asset, Route B: fresh CC0 MPFB body, casualsuit02 long-sleeve teal top and denim trousers, shoes01 adapted to low footwear. No uniform, insignia, equipment or original shirt logo. Source photos remain untouched.\n\nTwo mutually exclusive baked poses, facing Blender +Y on the approved Voi, common ground/axle origin. <=35,000 triangles per pose, single opaque 2048 atlas baked from ride only; matching index topology and UVs. Editable source rig in rider_rig.blend (native MPFB -Y; export rotates geometry pi about Z), poses on frames 1/2. Build: Blender 5.2 --background --factory-startup --threads 8 --python-exit-code 1 --python build.py; export independently with --python export.py. Validate with python verify.py.\n\nDeck/grip targets are in spec.json. Analytic limb solves fail on unreachable targets rather than silently clamping. Both soles checked from adopted foot source indices; short source collars are trimmed to avoid bent trouser penetration. Actual approved scooter dashboard versus evaluated body and clothing triangle intersections are tested in preview.py before rendering. Contact renders are in previews/, including final fit board.\n''')
print('PROVENANCE',len(paths),'hashed files')
